N_THREADS = 8
INCREMENTS_PER_THREAD = 25
EXPECTED_FINAL = SEED_BALANCE + N_THREADS * INCREMENTS_PER_THREAD * INCREMENT
ROUNDS = 5


def _hammer(increment_fn, db_path: str) -> int:
    """Run N_THREADS threads x INCREMENTS_PER_THREAD increments; return final balance."""
    threads = [
        threading.Thread(
            target=lambda: [increment_fn(db_path) for _ in range(INCREMENTS_PER_THREAD)]
        )
        for _ in range(N_THREADS)
    ]
    for t in threads:
        t.start()
    for t in threads:
        t.join(timeout=120)
    assert not any(t.is_alive() for t in threads), "worker thread hung"
    conn = sqlite3_connect(db_path)
    try:
        return read_balance(conn)
    finally:
        conn.close()


def sqlite3_connect(db_path):
    from fix_a import connect
    return connect(db_path)


class TestAnomaly:
    def test_anomaly(self):
        """Prove the reproduction: exactly the WRONG outcome (1100, not 1200)."""
        final = run_anomaly()
        wrong = SEED_BALANCE + INCREMENT  # one update lost
        correct = SEED_BALANCE + 2 * INCREMENT
        assert final == wrong == 1100, f"expected lost update ({wrong}), got {final}"
        assert final != correct, "anomaly did not reproduce"


